PRAGMA foreign_keys=ON;
CREATE TABLE users(id TEXT PRIMARY KEY,username TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)),created_at INTEGER NOT NULL);
CREATE TABLE user_roles(user_id TEXT NOT NULL REFERENCES users(id),role TEXT NOT NULL CHECK(role IN('BAR','TOPUP','MARKET_MANAGER','PAYMENT_LEAD','ADMIN','AUDITOR')),PRIMARY KEY(user_id,role));
CREATE TABLE terminals(id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE,bar TEXT NOT NULL CHECK(bar IN('BAR_A','BAR_B','CENTRAL','ADMIN')),status TEXT NOT NULL DEFAULT 'ACTIVE',created_at INTEGER NOT NULL);
CREATE TABLE wristbands(id TEXT PRIMARY KEY,band_number TEXT NOT NULL UNIQUE,uid_hex TEXT NOT NULL UNIQUE,status TEXT NOT NULL DEFAULT 'IMPORTED' CHECK(status IN('IMPORTED','ACTIVE','BLOCKED','RETIRED')),created_at INTEGER NOT NULL,CHECK(uid_hex NOT GLOB '*[^0-9A-F]*' AND length(uid_hex) IN(8,14,20)));
CREATE TABLE wallets(id TEXT PRIMARY KEY,balance_cents INTEGER NOT NULL DEFAULT 0 CHECK(balance_cents>=0),status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK(status IN('ACTIVE','FROZEN','CLOSED')),version INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL);
CREATE TABLE wristband_assignments(id TEXT PRIMARY KEY,wristband_id TEXT NOT NULL REFERENCES wristbands(id),wallet_id TEXT NOT NULL REFERENCES wallets(id),assigned_at INTEGER NOT NULL,revoked_at INTEGER,reason TEXT,operator_id TEXT REFERENCES users(id));
CREATE UNIQUE INDEX assignment_active_band ON wristband_assignments(wristband_id) WHERE revoked_at IS NULL;
CREATE UNIQUE INDEX assignment_active_wallet ON wristband_assignments(wallet_id) WHERE revoked_at IS NULL;
CREATE TABLE ledger_accounts(id TEXT PRIMARY KEY,type TEXT NOT NULL CHECK(type IN('WALLET','CASH_CLEARING','CARD_CLEARING','SALES','REFUND_CLEARING')),wallet_id TEXT UNIQUE REFERENCES wallets(id),currency TEXT NOT NULL DEFAULT 'EUR',created_at INTEGER NOT NULL,CHECK((type='WALLET' AND wallet_id IS NOT NULL) OR (type<>'WALLET' AND wallet_id IS NULL)));
CREATE TABLE financial_operations(id TEXT PRIMARY KEY,idempotency_key TEXT NOT NULL UNIQUE,request_hash TEXT NOT NULL,type TEXT NOT NULL CHECK(type IN('TOPUP','PURCHASE','REFUND','ADJUSTMENT')),status TEXT NOT NULL CHECK(status IN('PENDING','COMMITTED','REJECTED')),terminal_id TEXT REFERENCES terminals(id),operator_id TEXT REFERENCES users(id),created_at INTEGER NOT NULL,committed_at INTEGER,response_json TEXT);
CREATE TABLE ledger_entries(id TEXT PRIMARY KEY,operation_id TEXT NOT NULL REFERENCES financial_operations(id),account_id TEXT NOT NULL REFERENCES ledger_accounts(id),amount_cents INTEGER NOT NULL CHECK(amount_cents<>0),created_at INTEGER NOT NULL);
CREATE INDEX ledger_operation_idx ON ledger_entries(operation_id);
CREATE TRIGGER ledger_entries_immutable_update BEFORE UPDATE ON ledger_entries BEGIN SELECT RAISE(ABORT,'ledger entries are immutable'); END;
CREATE TRIGGER ledger_entries_immutable_delete BEFORE DELETE ON ledger_entries BEGIN SELECT RAISE(ABORT,'ledger entries are immutable'); END;
CREATE TABLE products(id TEXT PRIMARY KEY,name TEXT NOT NULL,category TEXT NOT NULL,base_price_cents INTEGER NOT NULL,min_price_cents INTEGER NOT NULL,max_price_cents INTEGER NOT NULL,active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)),CHECK(min_price_cents<=base_price_cents AND base_price_cents<=max_price_cents));
CREATE TABLE price_versions(id TEXT PRIMARY KEY,version INTEGER NOT NULL UNIQUE,status TEXT NOT NULL CHECK(status IN('DRAFT','ACTIVE','SUPERSEDED')),effective_at INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE UNIQUE INDEX one_active_price_version ON price_versions(status) WHERE status='ACTIVE';
CREATE TABLE price_entries(price_version_id TEXT NOT NULL REFERENCES price_versions(id),product_id TEXT NOT NULL REFERENCES products(id),price_cents INTEGER NOT NULL CHECK(price_cents>=0),PRIMARY KEY(price_version_id,product_id));
CREATE TABLE quotes(id TEXT PRIMARY KEY,price_version_id TEXT NOT NULL REFERENCES price_versions(id),total_cents INTEGER NOT NULL CHECK(total_cents>0),items_json TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('OPEN','CONSUMED','EXPIRED')),expires_at INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE orders(id TEXT PRIMARY KEY,wallet_id TEXT NOT NULL REFERENCES wallets(id),quote_id TEXT NOT NULL UNIQUE REFERENCES quotes(id),operation_id TEXT NOT NULL UNIQUE REFERENCES financial_operations(id),terminal_id TEXT REFERENCES terminals(id),total_cents INTEGER NOT NULL CHECK(total_cents>0),status TEXT NOT NULL CHECK(status IN('PAID','REFUNDED')),created_at INTEGER NOT NULL);
CREATE TABLE topups(id TEXT PRIMARY KEY,wallet_id TEXT NOT NULL REFERENCES wallets(id),operation_id TEXT NOT NULL UNIQUE REFERENCES financial_operations(id),amount_cents INTEGER NOT NULL CHECK(amount_cents>0),funding_method TEXT NOT NULL CHECK(funding_method IN('CASH','CARD_VERIFIED')),payment_reference TEXT,status TEXT NOT NULL CHECK(status IN('COMMITTED','REVERSED')),created_at INTEGER NOT NULL,CHECK(funding_method='CASH' OR payment_reference IS NOT NULL));
CREATE TABLE system_state(id INTEGER PRIMARY KEY CHECK(id=1),mode TEXT NOT NULL CHECK(mode IN('NORMAL','PRICE_FROZEN','PAYMENT_STOP')),changed_at INTEGER NOT NULL,changed_by TEXT REFERENCES users(id),reason TEXT);
CREATE TABLE audit_events(id TEXT PRIMARY KEY,actor_id TEXT REFERENCES users(id),action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT,payload_json TEXT NOT NULL,previous_hash TEXT,event_hash TEXT NOT NULL UNIQUE,created_at INTEGER NOT NULL);
